import React from 'react';

export const ReportFilters = ({ value, onChange }) => <div className="sales-v2-filters" aria-label="Report filters"><label>From<input type="date" value={value.from} onChange={(event) => onChange({ ...value, from: event.target.value })} /></label><label>To<input type="date" value={value.to} onChange={(event) => onChange({ ...value, to: event.target.value })} /></label><label>Category<select value={value.category} onChange={(event) => onChange({ ...value, category: event.target.value })}><option value="">All categories</option><option value="agent">Agent</option><option value="sub_agent">Sub-agent</option></select></label><label>Status<select value={value.status} onChange={(event) => onChange({ ...value, status: event.target.value })}><option value="">All statuses</option><option value="registered">Registered</option><option value="appointment">Appointment</option><option value="interested">Interested</option></select></label></div>;
